import heapq

def merge_sorted_streams(*streams):
    streams = [stream for stream in streams]  # Convert to list if not already
    iterators = [iter(stream) for stream in streams]
    keys = [next(iterator, None) for iterator in iterators]

    while True:
        min_key = None
        min_index = -1
        for i, key in enumerate(keys):
            if key is not None and (min_key is None or key[0] < min_key[0]):
                min_key = key
                min_index = i
            elif key is not None and key[0] == min_key[0]:
                min_key = key
                min_index = i

        if min_key is None:
            break

        yield min_key
        keys[min_index] = next(iterators[min_index], None)
